export const AI_IN_DAILY_LIFE_ACTIVITIES = [
{n:1,type:"mcq",micro:"AI ada di mana-mana",q:"AI paling sering kita temui dalam bentuk...",options:["Program di dalam aplikasi & layanan sehari-hari: peta, kamera, media sosial, toko daring","Mesin besar yang bekerja di dalam pabrik dan jarang kita temui di rumah atau sekolah","Robot berbentuk manusia yang berjalan di jalan dan membantu pekerjaan rumah tangga kita"],answer:0,explain:"Kebanyakan AI tidak berbentuk fisik — ia bekerja di latar belakang aplikasi yang kita pakai tiap hari.",hint:"Pernahkah kamu memakai AI hari ini tanpa melihat robot?"},
{n:2,type:"mcq",micro:"Rekomendasi",q:"Saat aplikasi musik/video menyarankan 'yang mungkin kamu suka', ia...",options:["Membaca pikiran dan suasana hatimu lewat kamera, lalu memilih tontonan yang sedang kamu bayangkan","Mencari pola dari yang kamu & orang lain tonton/dengar sebelumnya, lalu menebak yang mirip","Memilih tontonan secara acak dari seluruh daftar, tanpa melihat apa yang pernah kamu tonton"],answer:1,explain:"Sistem rekomendasi mempelajari pola pilihan banyak orang untuk menebak apa yang cocok untukmu.",hint:"Data apa yang aplikasi punya tentang kebiasaanmu?"},
{n:3,type:"mcq",micro:"Peta & navigasi",q:"Aplikasi peta memperkirakan waktu tempuh & jalur tercepat dengan...",options:["Menelepon kantor polisi setiap beberapa menit untuk menanyakan jalan mana yang sedang lancar","Menebak dari peta tetap yang dibuat bertahun-tahun lalu, tanpa data pengguna yang sedang bergerak","Menggabungkan data kecepatan pergerakan banyak pengguna saat ini + pola lalu lintas historis"],answer:2,explain:"Peta memakai data agregat pergerakan (anonim) dari banyak ponsel untuk memperkirakan kondisi jalan.",hint:"Bagaimana aplikasi tahu ada kemacetan di jalan yang belum kamu lewati?"},
{n:4,type:"mcq",micro:"Asisten suara",q:"Asisten suara ('Hai, nyalakan lampu') memakai AI untuk...",options:["Mengenali bunyi ucapan → mengubahnya jadi teks → memahami maksud → menjalankan perintah","Merekam semua yang kamu katakan lalu mengunggahnya ke publik agar dapat didengar pengguna lain","Menebak lampu mana yang dimaksud dari kebiasaan menyala sendiri tiap malam, tanpa mendengar ucapan"],answer:0,explain:"Beberapa langkah AI: pengenalan suara, pemahaman bahasa, lalu tindakan.",hint:"Apa yang harus terjadi antara kamu berbicara dan lampu menyala?"},
{n:5,type:"mcq",micro:"Kamera & foto",q:"Kamera ponsel yang otomatis mengelompokkan foto berdasarkan orang, tempat, atau objek memakai AI untuk...",options:["Mengubah tanggal foto","Mengenali wajah & objek dalam gambar","Menghapus foto lama"],answer:1,explain:"Pengenalan gambar mengidentifikasi apa/siapa yang ada dalam foto agar bisa dikelompokkan & dicari.",hint:"Bagaimana galeri tahu foto mana yang ada 'anjing'-nya?"},
{n:6,type:"order",micro:"Alur sebuah fitur AI",q:"Urutkan langkah umum saat kamu memakai penerjemah otomatis.",items:["Kamu memberi masukan (kalimat yang ingin diterjemahkan)","AI memproses memakai pola bahasa yang dipelajarinya","AI memberi keluaran: kalimat terjemahan (tebakan terbaiknya)","Kamu memeriksa apakah hasilnya masuk akal untuk keperluanmu"],answer:[0,1,2,3],explain:"Masukan → pemrosesan → keluaran (tebakan) → verifikasi olehmu.",hint:"Kamu memberi sesuatu dulu, lalu AI menjawab."},
{n:7,type:"mcq",micro:"Filter & moderasi",q:"Media sosial yang otomatis menyembunyikan komentar spam/kasar memakai AI sebagai...",options:["Petugas manusia yang membaca setiap komentar satu per satu lalu menghapusnya dengan tangan","Kamera yang memotret layar penggunanya untuk menilai komentar mana yang pantas ditampilkan","Pengklasifikasi yang belajar dari contoh komentar yang ditandai orang sebagai spam/kasar/aman"],answer:2,explain:"Moderasi otomatis mengklasifikasikan konten berdasarkan pola dari contoh yang pernah dilabeli.",hint:"Bagaimana sistem 'tahu' sebuah komentar melanggar aturan?"},
{n:8,type:"mcq",micro:"Papan ketik prediktif",q:"Papan ketik yang menyarankan kata berikutnya memprediksi...",options:["Kata yang paling sering muncul setelah kata-kata yang sudah kamu ketik, berdasarkan pola bahasa","Kata yang sedang dipikirkan temanmu saat mengetik di ponsel lain, lewat sinyal rahasia antar perangkat","Cuaca di tempatmu hari ini, berdasarkan huruf yang kamu ketik dan lokasi ponsel yang terbaca"],answer:0,explain:"Model bahasa kecil memperkirakan kata berikutnya yang paling mungkin dari pola teks.",hint:"Setelah 'Selamat', kata apa yang biasanya menyusul?"},
{n:9,type:"mcq",micro:"Deteksi penipuan",q:"Bank yang menandai transaksi mencurigakan memakai AI untuk...",options:["Menebak saldo tabungan nasabah lain dari nama pemilik rekening dan alamat rumah yang terdaftar","Mengenali pola transaksi yang tidak biasa bagi seorang nasabah (lokasi asing, nominal aneh, waktu tak biasa)","Membuka dan membaca isi rekening seluruh nasabah untuk memilih siapa yang pantas dapat kartu kredit baru"],answer:1,explain:"Sistem deteksi penipuan belajar pola belanja normal tiap nasabah & menandai yang menyimpang jauh.",hint:"Apa yang membuat sebuah transaksi terlihat 'tidak seperti biasanya'?"},
{n:10,type:"tf",micro:"Tidak semua otomatisasi adalah AI",q:"Benar atau Salah: Termostat yang menyalakan pemanas saat suhu di bawah 20°C dan mematikannya di atas 22°C adalah AI yang belajar.",answer:false,explain:"Itu aturan tetap sederhana ('jika ... maka ...'), bukan pola yang dipelajari dari data. Tidak semua perilaku otomatis adalah AI.",hint:"Bisakah perilakunya dijelaskan dengan satu kalimat 'jika ... maka ...'?"},
{n:11,type:"mcq",micro:"AI vs pencarian biasa",q:"Bertanya ke mesin pencari biasa berbeda dari bertanya ke AI percakapan karena mesin pencari umumnya...",options:["Menyusun jawaban dari nol dengan meniru gaya bicara orang, bukan menunjukkan daftar halaman","Bekerja hanya saat tidak ada internet dan memakai arsip salinan halaman web di ponselmu","Menunjukkan daftar tautan ke halaman yang sudah ada, bukan menyusun jawaban kalimat sendiri"],answer:2,explain:"Mesin pencari mengambil halaman relevan; AI percakapan menyusun kalimat baru. Keduanya berguna untuk hal berbeda.",hint:"Kamu menerima daftar tautan, atau paragraf yang ditulis untukmu?"},
{n:12,type:"mcq",micro:"Personalisasi",q:"Dua orang bertanya 'film apa yang bagus?' ke aplikasi yang sama & mendapat saran berbeda karena...",options:["AI mempertimbangkan riwayat & pola tiap pengguna (personalisasi)","Aplikasinya rusak lalu memberi jawaban yang berubah tanpa alasan jelas","Salah satu dari keduanya berbohong tentang selera film kepada aplikasinya"],answer:0,explain:"Sistem menyesuaikan keluaran dengan data tiap pengguna, jadi jawabannya berbeda-beda.",hint:"Informasi apa yang aplikasi punya tentang tiap orang?"},
{n:13,type:"mcq",micro:"AI di balik layar sekolah",q:"Contoh AI yang mungkin dipakai di lingkungan sekolah:",options:["Meja dan kursi kelas yang terbuat dari kayu, lengkap dengan laci kecil untuk menyimpan buku dan alat tulis","Alat cek kemiripan tugas (plagiarisme), rekomendasi bacaan di perpustakaan digital, penilaian pilihan ganda otomatis","Papan tulis dan spidol yang dipakai guru menulis, dihapus dengan penghapus biasa setiap pergantian pelajaran"],answer:1,explain:"AI di sekolah sering berupa alat bantu administratif & pembelajaran, bukan robot.",hint:"Alat digital apa di sekolah yang harus 'menebak' atau 'mengenali' sesuatu?"},
{n:14,type:"tf",micro:"AI menebak, bukan memastikan",q:"Benar atau Salah: Ketika aplikasi cuaca berkata 'kemungkinan hujan 70%', itu berarti AI sudah memastikan hujan akan turun hari itu.",answer:false,explain:"AI prediksi memberi kemungkinan, bukan kepastian. '70%' berarti pada situasi serupa di masa lalu, hujan turun sekitar 7 dari 10 kali.",hint:"Apa arti angka persen pada ramalan?"},
{n:15,type:"mcq",micro:"AI bisa salah",q:"Aplikasi kamera menandai anak anjing sebagai 'kucing'. Ini menunjukkan...",options:["Anjing dan kucing sebenarnya hewan yang sama, jadi nama apa saja boleh dipakai","Anak anjing memang kucing kecil, sehingga aplikasinya tidak keliru dalam hal ini","AI bisa keliru, terutama kalau contoh latihnya kurang atau gambarnya membingungkan"],answer:2,explain:"AI menebak berdasarkan pola. Kalau polanya mirip atau datanya terbatas, tebakannya bisa keliru.",hint:"Apakah 'tebakan terbaik' selalu berarti 'tebakan benar'?"},
{n:16,type:"mcq",micro:"Iklan yang dipersonalisasi",q:"Iklan yang 'mengikuti'-mu di berbagai aplikasi setelah kamu mencari sesuatu bekerja karena...",options:["Sistem iklan memakai data aktivitasmu (pencarian, kunjungan) untuk menebak apa yang mungkin kamu beli","Kebetulan saja karena banyak aplikasi menampilkan iklan yang sama kepada setiap pengguna di hari yang sama","Iklan itu membaca pikiranmu lewat mikrofon ponsel saat kamu sedang memikirkan barang yang ingin dibeli"],answer:0,explain:"Iklan bertarget memakai profil aktivitas untuk memilih iklan yang kemungkinan menarik bagimu — ini juga sistem berbasis AI/data.",hint:"Dari mana iklan 'tahu' kamu baru mencari sepatu?"},
{n:17,type:"mcq",micro:"AI menyaring, kamu tidak melihat semuanya",q:"Umpan (feed) media sosial yang kamu lihat adalah...",options:["Seluruh unggahan dari akun yang kamu ikuti, ditampilkan berurutan menurut waktu tanpa dipilih sistem","Sebagian kecil yang dipilih & diurutkan AI berdasarkan tebakan apa yang membuatmu tetap memakai aplikasi","Daftar tetap yang sama untuk setiap pengguna, disusun oleh pemilik aplikasi dan jarang diubah sepanjang tahun"],answer:1,explain:"Umpan modern disaring & diurutkan algoritma. Kamu tidak melihat semuanya, dan urutannya bukan kebetulan.",hint:"Apakah kamu melihat SEMUA unggahan teman-temanmu, atau hanya sebagian?"},
{n:18,type:"mcq",micro:"AI membantu tugas berulang",q:"AI paling cocok mengambil alih tugas yang...",options:["Membutuhkan penilaian moral yang berat dan menyangkut nasib orang, sehingga kesalahan kecil bisa fatal","Belum dikerjakan oleh orang lain sebelumnya, sehingga tidak ada contoh sedikit pun untuk dipelajari AI","Berulang, punya banyak contoh, & kesalahannya tidak fatal — seperti menyortir foto atau menyarankan kata"],answer:2,explain:"AI unggul pada tugas berpola & bervolume tinggi; ia lemah pada hal yang butuh penilaian nilai atau benar-benar baru.",hint:"Tugas seperti apa yang membosankan bagi manusia tapi punya pola jelas?"},
{n:19,type:"mcq",micro:"Manusia tetap di balik AI",q:"Kalau layanan AI membuat kesalahan yang merugikanmu, siapa yang bertanggung jawab?",options:["Perusahaan & orang yang merancang, menjual, & menerapkan layanan itu","AI itu sendiri, karena ia yang mengambil keputusan dan bukan manusia","Pengguna saja, karena ia yang memilih memakai layanan tersebut"],answer:0,explain:"AI adalah alat. Tanggung jawab tetap pada manusia & lembaga di baliknya.",hint:"Bisakah sebuah alat dimintai pertanggungjawaban?"},
{n:20,type:"open",micro:"AI dalam satu hariku",q:"Tuliskan garis waktu satu hari biasamu & tandai minimal 4 titik di mana kamu kemungkinan berinteraksi dengan AI. Untuk tiap titik, sebutkan tugas 'pintar' apa yang AI lakukan (mengenali, memprediksi, merekomendasikan, mengklasifikasi).",explain:"Jawaban baik menyebut titik interaksi nyata DAN jenis tugas kecerdasan (mengenali/memprediksi/merekomendasi/mengklasifikasi) di tiap titik.",hint:"Pikirkan: papan ketik, peta, kamera, media sosial, toko daring, email, asisten suara.",sample:"Pagi: alarm ponsel (bukan AI). Buka aplikasi berita — AI merekomendasikan artikel berdasarkan bacaanku. Mengetik pesan — papan ketik memprediksi kata berikutnya. Perjalanan sekolah — aplikasi peta memprediksi waktu tempuh & rute dari data lalu lintas. Siang: foto kegiatan — galeri mengenali & mengelompokkan wajah. Sore: buka aplikasi video — AI merekomendasikan video berikutnya & filter komentar spam. Malam: cek email — filter spam mengklasifikasi pesan; asisten belanja daring merekomendasikan produk."},
{n:21,type:"mcq",micro:"Data yang menggerakkan rekomendasi",q:"Sistem rekomendasi belajar dari...",options:["Tebakan acak yang tidak bersumber dari data pengguna, lalu diperbaiki bila ada keluhan resmi","Apa yang kamu klik, tonton sampai habis, lewati, sukai, cari — & perilaku jutaan pengguna lain","Hanya nama dan umurmu yang kamu isi saat mendaftar, tanpa memperhatikan perilaku di aplikasi"],answer:1,explain:"Setiap tindakanmu (dan tidak-bertindak) adalah sinyal. Sistem menggabungkannya untuk menebak preferensimu.",hint:"Apa saja 'jejak' yang kamu tinggalkan saat memakai aplikasi?"},
{n:22,type:"mcq",micro:"Sinyal sesaat membentuk umpan",q:"Kamu iseng menonton satu video sensasional sampai habis. Kemungkinan sistem...",options:["Mengabaikannya karena satu video sensasional tidak tercatat dalam riwayat tontonan dan tidak dihitung","Berhenti merekomendasikan video lain kepadamu sampai kamu menyetujui syarat penggunaan yang baru","Menyimpulkan kamu menyukai konten itu & menampilkannya lebih sering — memperkuat pola meski bukan minat sebenarnya"],answer:2,explain:"Sistem belajar dari perilaku, termasuk yang sesaat/iseng. Perhatikan sinyal yang kamu kirim.",hint:"Apa yang 'dipelajari' sistem dari setiap tontonanmu sampai habis?"},
{n:23,type:"mcq",micro:"Peta: dari mana data lalu lintas",q:"Aplikasi peta tahu ada kemacetan karena...",options:["Banyak ponsel di ruas jalan itu bergerak sangat lambat, dan datanya (anonim) dikumpulkan","Ada kamera yang dipasang di setiap ruas jalan dan mengirim foto kemacetan ke aplikasi peta","Aplikasi menebak dari ramalan cuaca saja, tanpa melihat pergerakan kendaraan atau ponsel"],answer:0,explain:"Data pergerakan agregat dari pengguna adalah sumber utama estimasi lalu lintas waktu nyata.",hint:"Apa yang bisa disimpulkan kalau ratusan ponsel di satu jalan hampir tidak bergerak?"},
{n:24,type:"classify",micro:"Jenis tugas AI sehari-hari",q:"Kelompokkan tiap fitur ke jenis tugasnya: 'Mengenali/klasifikasi', 'Memprediksi angka/nilai', atau 'Menghasilkan konten'.",items:["Galeri menandai foto yang ada kucingnya","Aplikasi peta memperkirakan tiba dalam 23 menit","Asisten menulis draf ucapan ulang tahun","Email memilah pesan ke folder Spam"],groups:["Mengenali/klasifikasi","Memprediksi angka/nilai","Menghasilkan konten"],answer:{"Mengenali/klasifikasi":["Galeri menandai foto yang ada kucingnya","Email memilah pesan ke folder Spam"],"Memprediksi angka/nilai":["Aplikasi peta memperkirakan tiba dalam 23 menit"],"Menghasilkan konten":["Asisten menulis draf ucapan ulang tahun"]},explain:"Klasifikasi memilih kategori; prediksi menghasilkan angka; generatif membuat konten baru.",hint:"Hasilnya kategori, angka, atau karya baru?"},
{n:25,type:"mcq",micro:"Asisten suara & privasi",q:"Kekhawatiran privasi umum tentang asisten suara yang 'selalu mendengarkan':",options:["Asisten suara tidak memakai mikrofon sehingga tidak mungkin merekam suara atau mengirimnya ke server di tempat lain","Apa yang direkam, dikirim ke mana, disimpan berapa lama, & apakah dipakai untuk melatih sistem — perlu dibaca kebijakannya","Tidak ada kekhawatiran, karena rekaman suara langsung terhapus sendiri begitu asisten selesai menjawab pertanyaanmu"],answer:1,explain:"Perangkat yang mendengarkan kata pemicu bisa mengirim rekaman setelah pemicu. Memahami & mengatur ini penting.",hint:"Ke mana perginya suaramu setelah kamu berbicara ke perangkat?"},
{n:26,type:"mcq",micro:"Terjemahan otomatis: kekuatan & batas",q:"Penerjemah otomatis paling andal untuk...",options:["Teks apa saja dengan sama andalnya, termasuk dokumen hukum, puisi, dan teks penuh nuansa budaya","Pekerjaan yang butuh ketepatan hukum, karena hasil terjemahan otomatis cukup untuk dijadikan bukti resmi","Memahami inti pesan santai; kurang andal untuk dokumen hukum, puisi, atau nuansa budaya yang halus"],answer:2,explain:"Untuk keperluan sehari-hari berisiko rendah, terjemahan otomatis cukup. Untuk teks penting/presisi, perlu penerjemah manusia.",hint:"Apa akibat terburuk kalau terjemahan menu restoran sedikit meleset, vs terjemahan kontrak?"},
{n:27,type:"mcq",micro:"Autokoreksi yang keliru",q:"Autokoreksi mengganti kata yang benar dengan kata lain. Ini terjadi karena...",options:["Sistem memprediksi kata 'lebih mungkin' dari pola umum, dan kadang salah menebak maksudmu","Ponsel sengaja mengganggu penggunanya dengan mengubah kata-kata supaya pesan menjadi kacau","Kamus autokoreksi milik ponsel itu rusak sehingga kata yang benar dianggap salah ejaan oleh sistem"],answer:0,explain:"Autokoreksi adalah prediksi. Ia menebak berdasarkan pola populer, yang tidak selalu cocok dengan maksudmu (nama, istilah khusus).",hint:"Mengapa autokoreksi sering salah pada nama orang atau kata daerah?"},
{n:28,type:"tf",micro:"Umpan yang dipersonalisasi bisa mempersempit pandangan",q:"Benar atau Salah: Sistem yang terus menyajikan konten mirip dengan yang kamu sukai justru memperluas ragam informasi & sudut pandang yang kamu temui seiring waktu.",answer:false,explain:"Sebaliknya — umpan yang terlalu dipersonalisasi bisa membuat 'gelembung filter': kita makin jarang bertemu pandangan atau informasi yang berbeda.",hint:"Kalau kamu hanya ditunjukkan hal yang kamu setujui, apa yang terjadi pada wawasanmu?"},
{n:29,type:"mcq",micro:"Rekomendasi pembelian",q:"Toko daring menyarankan 'sering dibeli bersama'. Ini berdasarkan...",options:["Tebakan acak komputer toko yang tidak melihat data pembelian","Pola pembelian banyak pelanggan lain yang membeli barang serupa","Selera pribadi pemilik toko yang memilih sendiri tiap pasangan barang"],answer:1,explain:"Sistem menemukan barang yang secara statistik sering muncul bersama di keranjang pelanggan.",hint:"Bagaimana toko tahu orang yang beli raket sering juga beli bola?"},
{n:30,type:"order",micro:"Bagaimana rekomendasi video terbentuk",q:"Urutkan bagaimana sebuah rekomendasi video sampai ke layarmu.",items:["Sistem mengumpulkan sinyal: riwayatmu, video yang ditonton orang mirip, judul & topik","Model memprediksi video mana yang kemungkinan kamu tonton lama / sukai","Sistem menyusun & mengurutkan daftar rekomendasi","Kamu menonton (atau melewati), dan tindakan itu jadi sinyal baru"],answer:[0,1,2,3],explain:"Kumpulkan sinyal → prediksi → urutkan → perilakumu jadi umpan balik untuk berikutnya.",hint:"Semuanya mulai dari data tentang apa yang kamu & orang lain lakukan."},
{n:31,type:"mcq",micro:"AI di kesehatan sehari-hari",q:"Jam tangan pintar yang memperingatkan detak jantung tidak normal memakai AI untuk...",options:["Menyembuhkan penyakit jantung lewat getaran khusus di pergelangan tangan, sehingga pemakai tidak perlu ke dokter","Menggantikan dokter dalam menentukan diagnosis dan memberi resep obat secara langsung kepada pemakai jam tangan itu","Mengenali pola sinyal jantung yang menyimpang dari normal — sebagai peringatan untuk memeriksakan diri, bukan diagnosis"],answer:2,explain:"AI kesehatan konsumen paling baik dipakai sebagai pemberi sinyal awal yang mendorong tindak lanjut oleh ahli.",hint:"Apa yang sebaiknya kamu lakukan setelah jam tanganmu memberi peringatan?"},
{n:32,type:"mcq",micro:"Chatbot layanan pelanggan",q:"Chatbot layanan pelanggan berguna untuk...",options:["Menjawab pertanyaan umum yang berulang dengan cepat; untuk masalah rumit/unik, sebaiknya dialihkan ke manusia","Menangani seluruh jenis masalah, termasuk yang rumit dan unik, sehingga petugas manusia tidak diperlukan","Menggantikan kebijakan perusahaan, karena chatbot berhak memutuskan sendiri ganti rugi untuk pelanggan"],answer:0,explain:"Chatbot menangani pola pertanyaan umum. Kasus yang di luar polanya butuh petugas manusia.",hint:"Kapan kamu ingin bicara dengan manusia sungguhan?"},
{n:33,type:"mcq",micro:"AI generatif dalam pekerjaan",q:"Alat AI yang membantu menulis email, membuat ringkasan, atau menghasilkan ide gambar paling baik dipakai sebagai...",options:["Sumber kebenaran final yang hasilnya boleh langsung dikirim tanpa diperiksa","Alat bantu draf pertama yang tetap perlu ditinjau, diperbaiki, & diverifikasi oleh manusia","Pengganti pekerja manusia, sehingga setelah dipakai orang tidak lagi perlu menulis atau memeriksa"],answer:1,explain:"AI generatif mempercepat awal pekerjaan; penilaian, akurasi, & tanggung jawab tetap pada manusia.",hint:"Apa yang harus kamu lakukan pada draf yang dibuat AI sebelum mengirimnya?"},
{n:34,type:"mcq",micro:"AI di rumah",q:"Perangkat 'rumah pintar' (lampu, kunci, kamera pintar) yang belajar kebiasaanmu...",options:["Aman bagi privasi karena perangkatnya hanya menyala di rumah, jadi pola hidupmu tidak perlu dipikirkan","Tidak mengumpulkan data karena hanya mengikuti jadwal yang kamu atur sendiri lewat tombol di dinding","Bisa nyaman, tapi mengumpulkan data pola hidupmu — pertimbangkan apa yang direkam & siapa yang bisa mengaksesnya"],answer:2,explain:"Kenyamanan rumah pintar datang dengan data tentang kapan kamu di rumah, kebiasaanmu, dsb. Perlu pertimbangan keamanan & privasi.",hint:"Informasi apa tentang keluargamu yang bisa disimpulkan dari perangkat rumah pintar?"},
{n:35,type:"mcq",micro:"AI vs kalkulator untuk hitungan",q:"Untuk perhitungan panjang yang harus tepat, alat yang lebih andal:",options:["Kalkulator atau program yang memang dirancang menghitung persis — model bahasa bisa keliru pada angka","Model bahasa yang lebih besar, karena hitungan panjang cukup dijawab dengan menebak pola angkanya","Meminta teman menebak hasilnya sekilas, karena tebakan manusia lebih teliti pada hitungan panjang"],answer:0,explain:"Model bahasa memprediksi teks, bukan menghitung. Untuk presisi angka, pakai alat hitung khusus.",hint:"Alat mana yang tugas utamanya memang berhitung?"},
{n:36,type:"tf",micro:"Layanan 'gratis' sering dibayar dengan data & perhatian",q:"Benar atau Salah: Banyak layanan AI 'gratis' menghasilkan uang lewat iklan & data pengguna, jadi 'gratis' bukan berarti tanpa biaya.",answer:true,explain:"Kalau kamu tidak membayar dengan uang, sering kamu 'membayar' dengan perhatian (iklan) dan data (untuk penargetan & pelatihan).",hint:"Bagaimana perusahaan di balik aplikasi gratis mendapat penghasilan?"},
{n:37,type:"mcq",micro:"AI dalam permainan",q:"Musuh dalam gim yang 'mengejar' pemain dengan cerdik...",options:["Dikendalikan pemain lain yang diam-diam duduk di balik layar dan menggerakkannya","Bisa memakai aturan sederhana yang dirancang tangan ATAU AI, tergantung pembuatnya","Harus memakai AI yang belajar dari jutaan pertandingan, bukan aturan sederhana"],answer:1,explain:"Tidak semua perilaku 'pintar' adalah AI yang belajar. Banyak gim memakai aturan tangan yang terasa cerdas.",hint:"Apakah perilaku cerdas selalu berarti 'belajar dari data'?"},
{n:38,type:"mcq",micro:"Notifikasi yang dioptimalkan",q:"Aplikasi mengirim notifikasi pada waktu tertentu karena...",options:["Jam di ponsel mengirim notifikasi mengikuti jadwal tetap yang sama untuk semua pengguna aplikasi itu","Pembuat aplikasi mengirimnya acak pada tengah malam untuk menguji apakah ponsel pengguna masih menyala","Sistem memprediksi kapan kamu paling mungkin membuka aplikasi & merespons — untuk memaksimalkan keterlibatan"],answer:2,explain:"Waktu & isi notifikasi sering dioptimalkan agar kamu kembali ke aplikasi. Menyadari ini membantu mengelola perhatian.",hint:"Mengapa notifikasi sering datang tepat saat kamu sedang santai?"},
{n:39,type:"mcq",micro:"Mengenali klaim berlebihan",q:"Iklan aplikasi: 'AI kami membaca emosimu dan menyembuhkan stres'. Sikap yang tepat:",options:["Skeptis — periksa apa sistemnya sebenarnya lakukan, adakah bukti independen, & apakah klaimnya dilebih-lebihkan","Percaya begitu saja karena ada kata 'AI' dan nama perusahaan besar dalam iklannya di toko aplikasi","Langsung beli dan pakai setiap hari karena iklannya menjanjikan hasil cepat bagi pengguna baru"],answer:0,explain:"Kata 'AI' sering dipakai untuk memberi kesan canggih. Periksa mekanisme & bukti sebelum percaya.",hint:"Apakah menempelkan kata 'AI' membuat sebuah klaim otomatis benar?"},
{n:40,type:"open",micro:"Membongkar sebuah fitur AI",q:"Pilih satu fitur AI yang kamu pakai rutin. Jelaskan: (1) apa tugas 'pintar'-nya, (2) data apa yang kemungkinan ia pakai (tentangmu & tentang orang lain), (3) satu cara ia bisa keliru & bagaimana itu terasa, (4) satu hal yang bisa kamu lakukan untuk memakainya lebih bijak.",explain:"Jawaban baik menghubungkan tugas–data–kesalahan–tindakan, menunjukkan pemahaman bahwa fitur itu berbasis pola dari data & bisa dikendalikan sebagian oleh pengguna.",hint:"Pikirkan data yang kamu berikan tanpa sadar, dan cara mengambil kembali sebagian kendali.",sample:"Contoh: rekomendasi video. (1) Memprediksi video mana yang akan kutonton lama/sukai. (2) Data: riwayat tontonanku, apa yang kulewati, berapa lama kutonton, langganan; juga perilaku jutaan pengguna dengan pola mirip; judul & topik video. (3) Keliru: menyimpulkan aku suka topik tertentu dari satu tontonan iseng, lalu membanjiri umpanku dengan itu — terasa seperti aplikasi 'salah paham' tentang minatku & membuang waktu. (4) Bijak: sengaja menandai 'tidak tertarik' pada rekomendasi yang tidak kuinginkan, sesekali mencari topik baru secara manual agar umpan tidak menyempit, & membatasi waktu menonton dengan pengatur waktu."},
{n:41,type:"mcq",micro:"Kapan AI cocok untuk sebuah tugas",q:"AI cenderung cocok bila tugasnya...",options:["Belum pernah dilakukan orang dan tidak punya data, sehingga AI tidak punya bahan untuk dipelajari","Berpola, punya banyak contoh, toleran terhadap sedikit kesalahan, & tidak butuh penilaian nilai yang berat","Butuh empati mendalam dan keputusan moral rumit, sehingga kesalahan kecil bisa sangat merugikan orang lain"],answer:1,explain:"Cocokkan alat dengan tugas: AI kuat pada pola bervolume tinggi, lemah pada hal yang butuh konteks manusia & nilai.",hint:"Tugas seperti apa yang cocok untuk 'belajar dari banyak contoh'?"},
{n:42,type:"mcq",micro:"Kapan AI TIDAK cocok",q:"Untuk keputusan mana AI sebaiknya hanya membantu, dengan keputusan akhir di tangan manusia?",options:["Mengurutkan daftar belanja bulanan dari harga termurah","Memilih lagu latar untuk video kegiatan kelas kami","Menentukan apakah seseorang layak mendapat bantuan darurat"],answer:2,explain:"Semakin besar dampaknya pada hidup, kesehatan, hak, atau keuangan seseorang, semakin penting penilaian & tanggung jawab manusia.",hint:"Mana yang taruhannya nyawa atau hak seseorang?"},
{n:43,type:"mcq",micro:"Menilai taruhan sebuah kesalahan",q:"Sebelum mengandalkan keluaran AI, pertanyaan kunci:",options:["'Apa akibat terburuk kalau ini salah, dan bisakah aku menanggung/memeriksa/memperbaikinya?'","'Apakah jawabannya terdengar canggih dan meyakinkan sehingga orang lain kagum membacanya?'","'Apakah alat AI ini gratis dan tidak perlu mendaftar atau membayar sebelum dipakai?'"],answer:0,explain:"Kecocokan pemakaian AI bergantung pada taruhan. Kesalahan yang mudah dicek & diperbaiki lebih bisa ditoleransi.",hint:"Terjemahan menu vs terjemahan kontrak — mana yang boleh sedikit meleset?"},
{n:44,type:"mcq",micro:"Memeriksa keluaran AI",q:"Kamu memakai AI untuk membantu menulis laporan sains. Tanggung jawab atas kebenaran isinya ada pada...",options:["Gurumu, karena guru yang memberi tugas dan wajib memeriksa isi laporannya","Kamu, sebagai orang yang menyerahkannya — kamu wajib memeriksa & memahaminya","AI-nya, karena AI yang menulis kalimat dan menyusun fakta di dalamnya"],answer:1,explain:"AI adalah alat bantu. Orang yang memakai & menyerahkan hasil tetap bertanggung jawab memverifikasi & memahaminya.",hint:"Nama siapa yang tertera di laporan itu?"},
{n:45,type:"mcq",micro:"Mengelola gelembung filter",q:"Untuk mengurangi efek 'gelembung filter' dari umpan yang dipersonalisasi:",options:["Percaya bahwa umpan sudah menunjukkan gambaran lengkap dunia, jadi tak perlu mencari sumber lain","Berhenti memakai internet untuk jangka panjang dan tidak membuka media sosial maupun berita daring lagi mulai hari ini demi menghindari umpan","Sesekali cari topik/sumber berbeda secara sengaja, ikuti akun dengan pandangan beragam, & jangan hanya mengandalkan satu umpan"],answer:2,explain:"Kamu bisa 'melawan arus' algoritma dengan kebiasaan aktif mencari keragaman informasi.",hint:"Apa yang bisa kamu lakukan agar tidak hanya melihat yang sudah kamu setujui?"},
{n:46,type:"mcq",micro:"Sinyal yang kamu kirim ke sistem",q:"Menyadari bahwa 'setiap klik, tonton, & suka adalah sinyal' membantu kamu...",options:["Lebih sadar membentuk umpanmu sendiri — mengklik sengaja hal yang benar-benar kamu minati, menandai yang tidak","Merasa tidak berdaya, karena umpan ditentukan sepenuhnya oleh sistem dan klikmu tidak berarti bagi aplikasinya","Berhenti memakai aplikasi dalam jangka panjang supaya klik dan tontonanmu tidak dicatat oleh sistem"],answer:0,explain:"Kamu tidak sepenuhnya pasif. Perilaku yang disengaja membentuk apa yang sistem tunjukkan berikutnya.",hint:"Bagaimana kamu 'melatih' umpanmu agar lebih berguna?"},
{n:47,type:"order",micro:"Memutuskan apakah memakai alat AI untuk sebuah tugas",q:"Urutkan langkah memutuskan apakah memakai alat AI untuk suatu tugas.",items:["Perjelas tugasnya & seberapa besar taruhan kesalahannya","Nilai apakah tugas itu berpola & apakah AI biasanya andal untuk jenis ini","Kalau dipakai: rencanakan bagaimana kamu akan memeriksa & memverifikasi keluarannya","Putuskan tingkat ketergantungan: bantuan draf, atau keputusan akhir manusia"],answer:[0,1,2,3],explain:"Perjelas taruhan → nilai kecocokan → rencanakan verifikasi → tetapkan tingkat ketergantungan.",hint:"Mulai dari 'apa akibatnya kalau ini salah'."},
{n:48,type:"mcq",micro:"Kombinasi manusia + AI",q:"Untuk pekerjaan serius, pembagian peran manusia–AI yang sehat:",options:["Manusia sebaiknya menghindari AI dalam pekerjaan serius, karena hasil AI keliru dan berbahaya bahkan di bagian yang berulang","AI menangani bagian berulang & menyodorkan pilihan; manusia menetapkan tujuan, menilai konteks, & bertanggung jawab atas keputusan","AI menggantikan penilaian manusia sepenuhnya, sehingga manusia tidak lagi menetapkan tujuan, atau bertanggung jawab atas keputusan akhir"],answer:1,explain:"AI memperkuat kapasitas manusia; manusia memegang kemudi soal nilai, konteks, & pertanggungjawaban.",hint:"Siapa memegang kemudi, siapa membantu mendorong?"},
{n:49,type:"mcq",micro:"Verifikasi fakta dari AI",q:"AI percakapan memberi 'fakta' dengan angka & tanggal spesifik. Sebelum memakainya:",options:["Percaya karena terdengar meyakinkan, lengkap dengan angka dan tanggal yang tampak teliti","Salin langsung ke tugas karena angka dan tanggal yang rinci menandakan fakta itu sudah diperiksa","Periksa dengan sumber tepercaya yang independen — detail presisi rawan keliru (halusinasi)"],answer:2,explain:"Model bisa 'mengarang' detail yang terdengar benar. Verifikasi mandiri wajib untuk hal penting.",hint:"Mana yang lebih rawan keliru: gaya penulisan, atau angka statistik spesifik?"},
{n:50,type:"mcq",micro:"AI & privasi data pribadi",q:"Sebelum mengunggah dokumen pribadi (rapor, surat, foto keluarga) ke layanan AI, pertimbangkan...",options:["Apakah data disimpan, dipakai melatih model, atau bisa diakses pihak lain — hindari mengunggah informasi sensitif ke layanan yang tidak jelas kebijakannya","Tidak perlu mempertimbangkan apa-apa, sebab dokumen yang diunggah langsung dihapus dan tak dibaca pihak lain, jadi aman untuk foto keluarga","Layanan AI dari perusahaan besar dianggap aman untuk dokumen pribadi, jadi cukup unggah dan abaikan kebijakan datanya, asalkan tampilannya rapi"],answer:0,explain:"Data yang kamu masukkan bisa disimpan atau dipakai lebih lanjut. Baca kebijakan & batasi berbagi info sensitif.",hint:"Ke mana perginya apa yang kamu unggah ke layanan itu?"},
{n:51,type:"open",micro:"Menilai kesesuaian AI untuk tiga tugas",q:"Untuk tiap tugas berikut, nilai apakah memakai AI (a) tepat & aman, (b) tepat dengan pengawasan manusia, atau (c) sebaiknya tidak — beri alasan: (1) merangkum bab buku pelajaran untuk membantu belajar, (2) menilai jawaban esai ujian akhir yang menentukan kelulusan, (3) menyusun draf undangan acara kelas.",explain:"Jawaban baik memilih tingkat yang sesuai taruhan tiap tugas, dengan alasan yang menyebut dampak kesalahan, kebutuhan verifikasi, & isu keadilan/bias.",hint:"Semakin besar dampak kesalahan pada hidup seseorang, semakin ke arah (c).",sample:"(1) Merangkum bab: (b) tepat dengan pengawasan — ringkasan AI mempercepat belajar, tapi harus dicek terhadap buku aslinya karena bisa melewatkan atau mengubah poin penting; jangan jadikan pengganti membaca. (2) Menilai esai penentu kelulusan: (c) sebaiknya tidak (atau paling banter AI hanya memberi penilaian awal yang SETIAP-nya ditinjau penuh oleh guru) — taruhannya besar, esai sarat konteks & kreativitas, model bisa bias terhadap gaya menulis tertentu, & siswa berhak digugat oleh manusia. (3) Draf undangan: (a) tepat & aman — taruhan rendah, mudah diperiksa & diperbaiki, tidak ada data sensitif; tetap dibaca ulang sebelum disebar."},
{n:52,type:"mcq",micro:"Ketergantungan berlebihan",q:"Selalu memakai AI untuk mengerjakan tugas tanpa mencoba sendiri berisiko...",options:["Guru akan senang karena semua tugas terisi rapi, dan nilai tugasmu jadi tinggi sehingga kamu belajar banyak","Kamu melewatkan proses berlatih yang membangun kemampuan, sehingga kesulitan saat AI tidak tersedia (ujian, dll.)","Hanya buang kuota internet, sebab kemampuanmu tetap bertambah karena melihat jawaban AI setiap hari"],answer:1,explain:"AI bisa memberi jawaban, tapi keterampilan tumbuh dari usaha. Pakai AI untuk memahami, bukan menggantikan latihan.",hint:"Apa tujuan sebenarnya dari soal latihan — jawaban benar, atau kemampuanmu?"},
{n:53,type:"tf",micro:"Literasi AI membuat pemakaian lebih aman & efektif",q:"Benar atau Salah: Orang yang memahami cara kerja & batas sistem AI sehari-hari biasanya bisa memanfaatkannya lebih efektif & lebih aman daripada yang menganggapnya ajaib atau menakutkan.",answer:true,explain:"Tahu apa yang bisa & tidak bisa dilakukan sistem, & di mana ia rapuh, adalah kunci memakainya dengan bijak.",hint:"Pengguna yang paham alat vs yang menganggapnya sihir — siapa yang lebih aman?"},
{n:54,type:"mcq",micro:"Mengelola waktu & perhatian",q:"Karena banyak aplikasi dirancang (dengan bantuan AI) untuk memaksimalkan waktu pemakaian, strategi menjaga kendali:",options:["Percaya bahwa kamu mengendalikan kebiasaanmu sendiri tanpa perlu batas, walau aplikasi dirancang menahan perhatianmu","Hapus seluruh aplikasi dari ponselmu dan jangan memakai layanan digital lagi untuk keperluan sehari-hari","Tetapkan batas waktu, matikan notifikasi tidak penting, & sadari kapan kamu 'ditarik' kembali ke aplikasi"],answer:2,explain:"Sistem ini pandai menarik perhatian. Pengaturan sadar (batas, notifikasi, kesadaran diri) membantu menyeimbangkannya.",hint:"Apa yang membuatmu terus membuka aplikasi meski tidak berniat?"},
{n:55,type:"mcq",micro:"AI & pekerjaan",q:"Pandangan paling seimbang tentang AI & pekerjaan:",options:["AI kemungkinan mengubah banyak pekerjaan — mengotomasi sebagian tugas, menciptakan tugas baru, & menggeser keterampilan yang dibutuhkan","AI akan menggantikan semua jenis pekerjaan manusia besok pagi, sehingga tidak akan ada orang yang bekerja lagi sesudahnya","AI tidak akan memengaruhi pekerjaan para pekerja, sekarang maupun di masa depan, sehingga dunia kerja tetap seperti dulu tanpa perubahan"],answer:0,explain:"Sejarah teknologi menunjukkan pergeseran, bukan sekadar penghapusan: sebagian tugas hilang, yang lain muncul, banyak peran berubah isinya.",hint:"Apakah teknologi masa lalu menghapus kerja sama sekali, atau mengubah bentuknya?"},
{n:56,type:"mcq",micro:"Menyikapi rekomendasi yang bias komersial",q:"Toko daring milik perusahaan X 'kebetulan' sering menampilkan produk X lebih dulu meski relevansinya sama dengan produk penjual lain. Sikap kritis:",options:["Beli saja produk yang ditampilkan pertama, karena toko menaruh barang terbaik dan termurah di urutan teratas bagi pembeli","Sadari rekomendasi bisa punya kepentingan komersial; bandingkan dengan pencarian manual & sumber lain sebelum membeli","Percaya pada urutan rekomendasi toko itu, sebab urutannya ditentukan relevansi dan bukan kepentingan toko yang menjualnya"],answer:1,explain:"Urutan rekomendasi tidak selalu murni 'yang terbaik untukmu'. Kepentingan pemilik platform bisa berperan.",hint:"Siapa yang diuntungkan kalau produk tertentu selalu muncul lebih dulu?"},
{n:57,type:"tf",micro:"Kamu bisa menyesuaikan banyak sistem AI",q:"Benar atau Salah: Pengguna tidak bisa berbuat apa-apa terhadap personalisasi & iklan bertarget; layanan tidak menyediakan pengaturan untuk membatasi atau mengelola data.",answer:false,explain:"Sebagian besar layanan besar justru punya pengaturan privasi & personalisasi (batasi personalisasi, hapus riwayat, matikan iklan bertarget). Menjelajahi & mengaturnya adalah cara nyata mengambil kembali kendali.",hint:"Sudahkah kamu membuka menu 'Pengaturan' & 'Privasi' aplikasi yang kamu pakai?"},
{n:58,type:"mcq",micro:"Mengajari orang lain",q:"Membantu anggota keluarga yang kurang paham teknologi mengenali AI di aplikasi mereka berguna karena...",options:["Mereka jadi tidak perlu lagi memakai ponsel karena aplikasi berbasis AI hanya berguna bagi anak muda","Mereka jadi takut pada teknologi dan menolak memakai aplikasi yang sebenarnya bermanfaat bagi mereka","Mereka jadi lebih waspada terhadap penipuan, iklan menyesatkan, & informasi keliru yang disebarkan sistem"],answer:2,explain:"Literasi AI yang menyebar membuat lebih banyak orang bisa memakai teknologi dengan aman & kritis.",hint:"Apa yang bisa terjadi pada orang yang tidak sadar bahwa umpan & iklan mereka dipilih algoritma?"},
{n:59,type:"mcq",micro:"Menilai alat AI baru sebelum memakainya",q:"Sebelum mulai memakai alat AI baru untuk hal penting, langkah bijak:",options:["Uji pada beberapa kasus yang jawabannya sudah kamu ketahui, baca untuk apa ia dirancang & batasnya, & cek kebijakan datanya","Langsung pakai untuk hal penting tanpa mencoba lebih dulu, karena alat yang populer sudah teruji dan hasilnya dapat dipercaya","Percaya ulasan bintang lima saja tanpa membaca batasan alatnya atau kebijakan datanya, karena banyak orang menyukainya"],answer:0,explain:"Menguji pada kasus yang kamu tahu jawabannya + memahami tujuan & batas alat = pemakaian yang lebih aman.",hint:"Bagaimana kamu tahu alat baru bisa dipercaya sebelum mengandalkannya?"},
{n:60,type:"open",micro:"Rencana pemakaian AI yang bijak",q:"Buat 'rencana pemakaian AI pribadi' dengan minimal 5 aturan untuk dirimu, mencakup: kapan boleh mengandalkan AI vs harus verifikasi, cara menjaga keterampilan tetap terlatih, pengelolaan data pribadi, pengelolaan waktu & perhatian, & menjaga keragaman informasi. Beri alasan singkat tiap aturan.",explain:"Rencana baik menyeimbangkan memanfaatkan AI dengan menjaga keterampilan, privasi, perhatian, keragaman informasi, & batas untuk keputusan berdampak — tiap aturan punya alasan.",hint:"Untuk tiap area (verifikasi, keterampilan, data, waktu, keragaman), tulis satu aturan konkret + alasannya.",sample:"(1) Untuk fakta, angka, atau kutipan yang akan kupakai di tugas/keputusan, selalu verifikasi dengan minimal satu sumber tepercaya lain — karena AI bisa 'mengarang' detail yang terdengar benar. (2) Untuk latihan soal (matematika, menulis), coba sendiri dulu; pakai AI untuk memahami langkah yang kubingungkan, bukan untuk jawaban jadi — agar keterampilanku tetap tumbuh untuk ujian tanpa AI. (3) Jangan unggah data sensitif (rapor, KTP keluarga, foto pribadi) ke layanan AI yang kebijakan datanya tidak jelas — karena data bisa disimpan/dipakai melatih. (4) Batasi aplikasi berbasis rekomendasi (video/medsos) maksimal X menit/hari dengan pengatur waktu, & matikan notifikasi non-penting — karena sistemnya dirancang menarik perhatianku. (5) Seminggu sekali, sengaja cari topik atau sumber berita di luar yang biasa direkomendasikan — agar umpanku tidak menyempit. (6) Untuk keputusan penting tentang orang lain (menilai, menuduh), jangan serahkan ke AI — keputusan itu butuh konteks & tanggung jawab manusia."},
{n:61,type:"mcq",micro:"Konten viral & emosi",q:"Konten yang memancing kemarahan atau ketakutan sering menyebar lebih cepat di media sosial karena...",options:["Konten marah dan takut sebenarnya lebih benar, sehingga pengguna menyebarkannya karena sudah diperiksa","Sistem sering mengutamakan konten yang memicu banyak reaksi/komentar, dan emosi kuat mendorong orang berbagi","Konten itu otomatis mendapat jaminan keaslian dari aplikasi, sehingga pengguna merasa aman membagikannya"],answer:1,explain:"Ukuran 'keterlibatan' bisa memberi keuntungan pada konten yang membangkitkan emosi, terlepas dari akurasi atau manfaatnya.",hint:"Jenis unggahan apa yang paling sering kamu lihat dikomentari ramai?"},
{n:62,type:"mcq",micro:"Deepfake & media palsu",q:"AI generatif bisa membuat foto, suara, & video palsu yang meyakinkan. Implikasinya:",options:["Video adalah bukti yang tak terbantahkan, jadi apa yang tampak di dalam video sudah benar-benar pernah terjadi di dunia nyata dan pada waktu yang disebutkan","Seluruh media di internet palsu, jadi tidak ada gunanya memeriksa sumber karena tidak ada satu pun yang bisa dipercaya","Kita perlu lebih hati-hati: periksa sumber, cari konfirmasi dari beberapa media tepercaya, & jangan langsung percaya karena 'ada videonya'"],answer:2,explain:"'Melihat' tidak lagi otomatis 'percaya'. Verifikasi sumber & konfirmasi silang jadi makin penting.",hint:"Apakah keberadaan sebuah video otomatis membuktikan kejadiannya nyata?"},
{n:63,type:"tf",micro:"'AI bilang' bukan bukti",q:"Benar atau Salah: Klaim 'menurut AI, kabar ini benar' bukan bukti bahwa kabar itu benar — verifikasi tetap pada sumber & bukti aslinya.",answer:true,explain:"'AI bilang' sering dipakai untuk memberi kesan otoritas palsu. AI bisa keliru & bisa dimanipulasi.",hint:"Apakah menempelkan kata 'AI' membuat sebuah klaim otomatis benar?"},
{n:64,type:"mcq",micro:"Rekomendasi yang menggiring ke ekstrem",q:"Beberapa sistem rekomendasi cenderung menyarankan konten yang makin lama makin 'kuat' atau ekstrem untuk mempertahankan perhatian. Cara menyikapi:",options:["Sadari polanya, sering menyetel ulang umpan (menandai tidak tertarik, mencari topik seimbang), & tidak menganggap yang direkomendasikan sebagai 'yang penting/benar'","Ikuti saja ke mana rekomendasi membawamu, sebab sistem tahu konten mana yang terbaik dan penting bagimu, jadi tidak perlu menyetel ulang umpan atau mencari topik lain","Percaya bahwa rekomendasi netral dan tak dipengaruhi tujuan mempertahankan perhatian, jadi tidak perlu disetel ulang, dan yang muncul di umpan adalah yang penting dan benar"],answer:0,explain:"Kesadaran akan dinamika ini + kebiasaan menyeimbangkan umpan mengurangi risiko digiring ke pandangan sempit/ekstrem.",hint:"Ke arah mana rekomendasi cenderung membawamu kalau kamu terus mengikutinya?"},
{n:65,type:"mcq",micro:"Keputusan yang tampak 'diputuskan AI'",q:"Berita: 'AI menolak 2.000 pengajuan bantuan bulan ini.' Cara paling tepat memahaminya:",options:["AI bertindak sendirian melawan keinginan lembaga itu, tanpa ada manusia yang merancang, mengatur, atau menyetujui cara kerjanya","Sebuah lembaga memakai sistem AI, yang dirancang & diatur manusia, sebagai bagian dari proses — tanggung jawab tetap pada lembaga itu","AI adalah pihak yang bertanggung jawab penuh dan memilih sendiri untuk menolak, sedangkan lembaganya tidak ikut terlibat dalam proses itu"],answer:1,explain:"Menyebut 'AI yang memutuskan' menyamarkan pilihan manusia: siapa yang membangun sistem, menetapkan ambang, & mengizinkannya berjalan tanpa peninjauan.",hint:"Ganti 'AI menolak' dengan 'lembaga X, memakai alat AI, menolak' — apa yang jadi lebih jelas?"},
{n:66,type:"tf",micro:"AI meyakinkan meski salah",q:"Benar atau Salah: Salah satu risiko AI percakapan adalah nada jawabannya tetap tenang & meyakinkan bahkan ketika isinya keliru, sehingga orang mudah percaya begitu saja.",answer:true,explain:"AI tidak menandai keraguannya seperti manusia. Gaya yang selalu percaya diri membuat kesalahan lebih sulit dikenali.",hint:"Apakah AI terdengar ragu saat ia sebenarnya salah?"},
{n:67,type:"mcq",micro:"Transparansi penggunaan AI",q:"Mengapa penting mengetahui bahwa sebuah keputusan (mis. penolakan pinjaman, penilaian) dibuat 'dengan bantuan AI'?",options:["Agar masyarakat dapat memuji AI dan berterima kasih langsung kepada mesin yang membuat keputusan","Tidak penting, karena hasil akhir yang dilihat orang lebih berharga daripada siapa yang membuat keputusan itu","Agar orang yang terdampak bisa mempertanyakan, meminta penjelasan, & mengajukan keberatan atas keputusan itu"],answer:2,explain:"Transparansi memungkinkan akuntabilitas: orang berhak tahu bagaimana keputusan yang memengaruhi mereka dibuat & bisa menggugatnya.",hint:"Kalau kamu ditolak, apa yang ingin kamu ketahui?"},
{n:68,type:"mcq",micro:"Data pribadi sebagai 'mata uang'",q:"Model bisnis 'layanan gratis dibayar dengan data' berarti...",options:["Datamu (aktivitas, minat, lokasi, kontak) dikumpulkan & dipakai untuk penargetan iklan atau dijual — nilai yang kamu 'bayar'","Layanan benar-benar tanpa biaya, sebab perusahaan membiayainya dari kebaikan hati pemiliknya dan tidak mengambil keuntungan dari pengguna","Datamu tidak berharga bagi perusahaan, sehingga mereka menyimpannya hanya karena ruang penyimpanannya masih kosong"],answer:0,explain:"Memahami bahwa data adalah bagian dari transaksi membantu memutuskan layanan mana yang layak dipakai & seberapa banyak berbagi.",hint:"Kalau produknya gratis, apa yang sebenarnya menjadi 'produk' yang dijual?"},
{n:69,type:"mcq",micro:"Menilai peringatan/deteksi otomatis",q:"Sistem sekolah menandai esai siswa sebagai 'kemungkinan dibuat AI'. Cara adil menyikapinya:",options:["Abaikan sepenuhnya dan jangan bicarakan dengan siswa, karena alat pendeteksi hanya dipakai di perguruan tinggi, bukan di sekolah","Perlakukan sebagai sinyal untuk dibicarakan dengan siswa, bukan vonis — alat pendeteksi teks AI tidak andal & bisa salah menuduh","Langsung beri sanksi kepada siswa itu, sebab hasil alat pendeteksi dianggap bukti yang kuat dan tidak perlu dibicarakan"],answer:1,explain:"Deteksi teks AI sering keliru (menuduh tulisan manusia, meloloskan tulisan AI). Keputusan penting tidak boleh bergantung pada alat semacam itu saja.",hint:"Seberapa yakin kamu bisa membuktikan siapa yang menulis sesuatu?"},
{n:70,type:"order",micro:"Menghadapi informasi mencurigakan di umpan",q:"Kamu melihat unggahan mengejutkan di media sosial. Urutkan langkah menyikapinya.",items:["Berhenti sejenak — jangan langsung membagikan karena emosi","Periksa sumbernya: siapa yang mengunggah, apakah media/lembaga tepercaya","Cari konfirmasi dari beberapa sumber independen tentang klaim yang sama","Kalau tidak terkonfirmasi atau tampak menyesatkan, jangan bagikan; pertimbangkan melaporkannya"],answer:[0,1,2,3],explain:"Jeda → cek sumber → konfirmasi silang → putuskan (jangan sebarkan yang belum terverifikasi).",hint:"Apa yang harus kamu lakukan SEBELUM menekan tombol 'bagikan'?"},
{n:71,type:"mcq",micro:"Otomatisasi vs otonomi",q:"AI yang menjalankan tugas yang ditetapkan manusia (otomatisasi) berbeda dari AI yang memilih tujuannya sendiri (otonomi penuh). AI sehari-hari saat ini...",options:["Sepenuhnya otonom: memilih sendiri tujuannya dan menentukan apa yang penting tanpa arahan manusia","Berhenti bekerja bila tidak ada manusia di dekatnya, lalu melanjutkan dengan tujuan buatannya sendiri","Menjalankan tujuan yang diberikan manusia; ia tidak memilih sendiri apa yang penting untuk dikejar"],answer:2,explain:"AI bisa sangat mandiri dalam melaksanakan tugas, tapi tujuan & nilainya berasal dari manusia yang merancangnya.",hint:"Siapa yang memutuskan APA yang dikejar sistem rekomendasi — 'waktu tonton' atau 'kesejahteraanmu'?"},
{n:72,type:"mcq",micro:"Menimbang kenyamanan vs privasi",q:"Fitur AI yang sangat nyaman (asisten yang tahu segalanya tentangmu) biasanya butuh...",options:["Akses ke banyak data pribadimu — kamu memilih titik keseimbangan antara kenyamanan & privasi yang kamu nyaman","Tidak butuh data pribadi, karena asisten bisa mengenalmu hanya dari suara dan tanpa riwayat aktivitasmu","Data orang lain saja, bukan datamu, sehingga kenyamanan dan privasimu tidak perlu dipertimbangkan"],answer:0,explain:"Sering ada pertukaran: makin personal & membantu sebuah asisten, makin banyak yang perlu ia ketahui tentangmu. Pilihannya milikmu.",hint:"Untuk asisten membantumu dengan baik, apa yang perlu ia ketahui tentangmu?"},
{n:73,type:"tf",micro:"AI tidak menghapus kebutuhan berpikir kritis",q:"Benar atau Salah: Memiliki akses ke AI berarti kita tidak perlu lagi belajar membaca kritis, berhitung, atau memeriksa fakta.",answer:false,explain:"Justru sebaliknya: karena AI bisa keliru dengan meyakinkan, keterampilan berpikir kritis & verifikasi menjadi makin penting.",hint:"Kalau alatmu kadang salah, apakah kamu jadi lebih butuh atau kurang butuh menilai sendiri?"},
{n:74,type:"mcq",micro:"Pengaruh AI pada opini publik",q:"Karena sistem rekomendasi membentuk apa yang jutaan orang lihat, mereka bisa...",options:["Hanya memengaruhi individu satu per satu dan tidak memengaruhi percakapan atau pendapat masyarakat secara luas, walau dipakai jutaan orang","Memengaruhi opini publik & percakapan masyarakat secara luas — sehingga bagaimana sistem itu dirancang & diawasi adalah kepentingan publik","Tidak berpengaruh pada masyarakat, karena apa yang dilihat jutaan orang tidak memengaruhi apa yang mereka pikirkan atau bicarakan"],answer:1,explain:"Skala sistem rekomendasi membuat pilihan desainnya (apa yang dipromosikan/ditekan) berdampak sosial, bukan sekadar personal.",hint:"Kalau satu sistem memutuskan apa yang dilihat jutaan orang, seberapa besar pengaruhnya?"},
{n:75,type:"mcq",micro:"Menyikapi klaim 'AI netral'",q:"Klaim 'algoritma kami netral, hanya menunjukkan apa yang orang mau' perlu disikapi hati-hati karena...",options:["Algoritma itu netral karena hanya menjalankan perhitungan, sehingga tidak ada keputusan desain yang membentuk hasilnya sedikit pun","Klaim itu benar karena perusahaan tahu persis yang orang inginkan, jadi tidak ada gunanya mempertanyakan cara kerjanya di balik layar","Pilihan tentang apa yang diukur & diutamakan (klik? waktu? keragaman?) sudah membentuk hasil — 'netral' menyembunyikan keputusan desain"],answer:2,explain:"Tidak ada sistem tanpa pilihan nilai. 'Memberi orang apa yang mereka mau' sendiri adalah pilihan yang bisa merugikan (mis. mendorong kecanduan/sensasi).",hint:"Siapa yang memilih ukuran keberhasilan sistem, & apakah itu 'netral'?"},
{n:76,type:"mcq",micro:"Batas kemampuan AI sehari-hari",q:"Manakah yang PALING sulit dijamin benar oleh AI percakapan saat ini?",options:["Memberi angka statistik spesifik atau kutipan persis tanpa akses ke sumber terverifikasi","Membuat daftar ide untuk judul karangan, nama kelompok, atau nama kegiatan di sekolah","Meniru gaya penulisan tertentu, misalnya gaya surat resmi, gaya puisi, atau gaya cerita anak"],answer:0,explain:"Detail presisi rawan keliru karena model memprediksi teks yang 'terdengar benar', bukan mengambil dari basis data terverifikasi.",hint:"Mana yang butuh ketepatan persis, bukan sekadar 'terdengar masuk akal'?"},
{n:77,type:"tf",micro:"Kamu punya lebih banyak kendali daripada yang terasa",q:"Benar atau Salah: Meski sistem AI dirancang untuk memengaruhi perilaku kita, kita tetap punya pilihan nyata: pengaturan yang bisa diubah, kebiasaan yang bisa dibentuk, & sikap kritis yang bisa dilatih.",answer:true,explain:"Menyadari pengaruh sistem bukan berarti tak berdaya. Kesadaran + tindakan sadar mengembalikan sebagian kendali.",hint:"Antara 'sepenuhnya dikendalikan' & 'sepenuhnya bebas', di mana kenyataannya?"},
{n:78,type:"mcq",micro:"Menilai 'asisten belajar AI'",q:"Sebuah aplikasi mengklaim 'AI kami mempersonalisasi pembelajaran & menjamin nilaimu naik'. Pertanyaan kritis:",options:["Berapa harganya saja, karena yang penting hanyalah apakah aplikasi itu murah atau mahal bagi orang tua dan sekolah kita","Bukti independen apa? Data siswa dipakai bagaimana? Apakah menggantikan pemahaman guru? Apa yang terjadi kalau AI-nya keliru menilai kemampuanku?","Tidak perlu bertanya, klaimnya sudah meyakinkan dan terbukti karena perusahaannya sendiri yang menjamin nilaimu naik di sekolah"],answer:1,explain:"Klaim 'menjamin' + 'AI' patut dipertanyakan. Periksa bukti, penggunaan data, & peran guru.",hint:"Klaim mana yang terdengar 'terlalu bagus untuk jadi kenyataan'?"},
{n:79,type:"mcq",micro:"Peran regulasi",q:"Aturan pemerintah/lembaga tentang transparansi & keadilan sistem AI yang berdampak besar (kredit, kerja, layanan publik) berguna karena...",options:["Menghambat teknologi tanpa manfaat, sebab syarat dari luar hanya memperlambat perusahaan dan membuat layanan mahal bagi pengguna","Tidak diperlukan, karena perusahaan sudah memeriksa sendiri dan niat baik mereka cukup melindungi pengguna dalam keadaan biasa","Menetapkan syarat minimum & hak (diberi tahu, penjelasan, banding) sehingga perlindungan tidak bergantung semata pada niat baik perusahaan"],answer:2,explain:"Untuk sistem yang memengaruhi hak & kesempatan, standar bersama & akuntabilitas melindungi warga.",hint:"Apakah keselamatan makanan sebaiknya bergantung hanya pada niat baik tiap produsen?"},
{n:80,type:"open",micro:"Menganalisis pengaruh sebuah platform",q:"Pilih satu platform yang kamu pakai (media sosial, video, berita, toko daring). Analisis: (1) apa yang kemungkinan dioptimalkan sistemnya (klik? waktu? pembelian?), (2) bagaimana itu memengaruhi apa yang kamu lihat & lakukan, (3) satu efek yang menguntungkanmu & satu yang mungkin merugikanmu, (4) tiga langkah konkret untuk memakainya lebih sadar & terkendali.",explain:"Jawaban baik mengidentifikasi ukuran optimasi, menghubungkannya ke pengalaman nyata, menimbang manfaat & kerugian, & mengusulkan langkah kendali yang spesifik.",hint:"Mulai dari 'apa yang perusahaan ini ingin aku lakukan lebih banyak?'",sample:"Contoh: platform video pendek. (1) Kemungkinan dioptimalkan untuk waktu total menonton & jumlah video ditonton per sesi. (2) Umpanku diisi video yang secara pola membuat orang seperti aku terus menggulir; video yang tidak menahan perhatian jarang muncul; autoplay membuatku menonton lebih lama dari yang kuniatkan. (3) Menguntungkan: aku menemukan kreator & topik baru yang benar-benar kunikmati & kupelajari. Merugikan: aku sering kehilangan 40 menit tanpa sadar, & umpanku menyempit ke beberapa jenis konten saja. (4) Langkah: (a) matikan autoplay & pasang pengatur waktu 20 menit/hari; (b) sengaja menekan 'tidak tertarik' & mencari topik edukatif tertentu agar umpan bergeser; (c) tidak membuka aplikasi di jam belajar & sebelum tidur."},
{n:81,type:"mcq",micro:"Mengenali AI dalam skenario baru",q:"Manakah yang PALING mungkin BUKAN AI?",options:["Lampu lalu lintas yang berganti hijau tiap 60 detik dengan pengatur waktu tetap","Kamera yang membaca plat nomor kendaraan dari gambar yang ditangkap di jalan","Aplikasi yang meringkas buku panjang dengan memahami isinya lalu menulis kalimat baru"],answer:0,explain:"Lampu dengan pengatur waktu tetap hanya mengikuti aturan waktu — bukan pola yang dipelajari. Dua lainnya mengenali bahasa atau gambar.",hint:"Mana yang bisa dijelaskan dengan 'setiap 60 detik, ganti'?"},
{n:82,type:"mcq",micro:"Menimbang adopsi AI di sebuah konteks",q:"Sebuah perpustakaan mempertimbangkan chatbot AI untuk menjawab pertanyaan pengunjung. Pertimbangan seimbang:",options:["Jangan memakai AI di perpustakaan, karena chatbot sering salah dan tidak berguna bagi pengunjung, bahkan untuk pertanyaan sederhana yang jawabannya sama tiap hari dan tidak membutuhkan pustakawan","Manfaat (jawaban cepat 24 jam untuk pertanyaan umum) vs risiko (jawaban keliru, kehilangan sentuhan pustakawan, biaya, data pengunjung) — mungkin dipakai untuk FAQ sederhana dengan opsi 'hubungi pustakawan'","Pakai saja secepatnya dan gantikan seluruh pustakawan, karena itu modern dan perpustakaan lain juga begitu, tanpa perlu mempertimbangkan risiko jawaban keliru, biaya, atau data pengunjung"],answer:1,explain:"Keputusan adopsi menimbang manfaat nyata vs risiko & biaya dalam konteks spesifik, sering menghasilkan pemakaian terbatas + jalur ke manusia.",hint:"Untuk pertanyaan seperti apa chatbot cukup, & untuk apa pengunjung tetap butuh pustakawan?"},
{n:83,type:"tf",micro:"AI sehari-hari = pilihan desain manusia",q:"Benar atau Salah: Apa yang direkomendasikan, iklan yang ditampilkan, & notifikasi yang dikirim adalah 'kehendak AI' sendiri, terlepas dari pilihan manusia atau perusahaan.",answer:false,explain:"Di balik tiap fitur ada keputusan manusia tentang tujuan & ukuran (mis. mengejar 'waktu tonton'). Menyadari ini membantu kita menuntut desain yang lebih baik.",hint:"Siapa yang memutuskan sistem rekomendasi mengejar 'waktu tonton'?"},
{n:84,type:"mcq",micro:"Menyeimbangkan manfaat & bahaya",q:"Pandangan paling matang tentang AI dalam kehidupan sehari-hari:",options:["AI buruk dalam kehidupan sehari-hari, jadi sebaiknya kita hindari dan tidak memakai layanan yang memakainya, karena manfaat nyata yang diberikannya sangat sedikit bagi pengguna","AI netral dan baik bagi seluruh pengguna, jadi kita bisa memakainya tanpa waspada terhadap perhatian, privasi, misinformasi, atau ketimpangan, dan tidak perlu menuntut akuntabilitas","Sangat bermanfaat DAN berpotensi merugikan (perhatian, privasi, misinformasi, ketimpangan) — jadi kita nikmati manfaatnya sambil memakai dengan sadar & menuntut akuntabilitas"],answer:2,explain:"Menolak semua AI atau mempercayainya buta sama-sama keliru. Pemakaian sadar + tekanan untuk desain yang bertanggung jawab adalah jalan tengah.",hint:"Bisakah sesuatu sangat berguna & tetap perlu diwaspadai?"},
{n:85,type:"order",micro:"Memutuskan cara memakai sebuah alat AI baru",q:"Urutkan langkah sebelum mengadopsi alat AI baru untuk keperluan rutin.",items:["Perjelas untuk apa kamu memakainya & seberapa besar taruhan kesalahannya","Cari tahu bagaimana ia bekerja, batasnya, & kebijakan datanya","Uji pada beberapa kasus yang jawabannya kamu ketahui","Tetapkan aturan pribadi: kapan mengandalkan, kapan verifikasi, data apa yang tidak kamu bagikan"],answer:[0,1,2,3],explain:"Perjelas tujuan & taruhan → pahami cara kerja & kebijakan → uji → tetapkan aturan pemakaian.",hint:"Sebelum mengandalkan, buktikan sendiri bahwa ia bisa dipercaya untuk keperluanmu."},
{n:86,type:"mcq",micro:"AI & bahasa daerah",q:"AI cenderung berkinerja lebih baik untuk bahasa dengan banyak teks digital. Untuk penutur bahasa daerah, ini berarti...",options:["Layanan AI (terjemahan, suara, pencarian) sering kurang baik untuk mereka — kesenjangan yang perlu diperhatikan & didorong perbaikannya","Bahasa daerah tidak penting bagi teknologi, sebab penuturnya akan beralih ke bahasa besar dengan sendirinya dalam waktu dekat","Tidak ada dampak, karena model AI mempelajari bahasa baru dalam sekejap sehingga layanannya setara untuk semua bahasa di dunia ini"],answer:0,explain:"Ketimpangan data bahasa menjadi ketimpangan kualitas layanan — masalah keadilan yang nyata dalam kehidupan sehari-hari.",hint:"Siapa yang dirugikan kalau AI hanya bekerja baik untuk bahasa-bahasa besar?"},
{n:87,type:"mcq",micro:"Mengenali manipulasi berbasis AI",q:"Pesan: 'Video AI ini membuktikan tokoh X mengatakan Y — sebarkan sebelum dihapus!' Tanda bahaya:",options:["Pesan itu perlu segera disebarkan sebelum dihapus, sebab bila ada videonya berarti benar dan banyak orang perlu tahu","Tekanan untuk menyebar cepat + klaim 'video membuktikan' + tidak ada sumber tepercaya — kemungkinan manipulasi/deepfake","Tidak ada tanda bahaya di dalam pesan itu, karena pesan yang berisi video dan ajakan menyebarkan itu aman"],answer:1,explain:"Kombinasi urgensi, klaim bukti visual, & ketiadaan konfirmasi dari media tepercaya adalah pola misinformasi klasik, kini diperkuat AI generatif.",hint:"Mengapa seseorang ingin kamu menyebar SEBELUM memeriksa?"},
{n:88,type:"tf",micro:"Literasi AI adalah keterampilan warga",q:"Benar atau Salah: Memahami AI di kehidupan sehari-hari — apa yang bisa & tidak bisa dilakukannya, bagaimana ia memengaruhi kita, & hak kita terhadap sistem yang memengaruhi kita — adalah bagian dari menjadi warga yang cakap di dunia digital.",answer:true,explain:"AI memengaruhi informasi, kesempatan, & keputusan yang kita hadapi. Memahaminya memberdayakan kita untuk memakainya baik & menuntut yang lebih baik.",hint:"Apakah warga perlu memahami sistem yang membentuk informasi & keputusan yang mereka hadapi?"},
{n:89,type:"mcq",micro:"Menjaga keterampilan di era AI",q:"Agar tetap tumbuh sebagai pelajar meski AI tersedia:",options:["Serahkan seluruh tugas kepada AI supaya cepat selesai, karena kamu tidak perlu belajar menulis atau menghitung","Hindari AI sepenuhnya, bahkan untuk memeriksa pekerjaanmu, supaya kamu tidak tergoda memakainya saat mengerjakan tugas","Pakai AI untuk memahami & memeriksa, bukan menggantikan usaha; tetap berlatih menulis, berhitung, & menalar sendiri"],answer:2,explain:"AI sebagai tutor/pemeriksa memperkuat pembelajaran; AI sebagai pengganti usaha mengikisnya.",hint:"Apa bedanya memakai AI untuk 'menjelaskan langkahnya' vs 'memberi jawaban jadi'?"},
{n:90,type:"mcq",micro:"AI & keputusan kolektif keluarga/kelas",q:"Sebuah kelas ingin memutuskan apakah memakai alat AI untuk mengelola jadwal & pengumuman. Proses yang baik:",options:["Bahas bersama: manfaat, siapa yang datanya terlibat, apa yang terjadi kalau alatnya keliru/berhenti, & sepakati aturan pemakaian + jalur manual cadangan","Ketua kelas memutuskan sendiri tanpa bertanya kepada teman-teman, karena yang penting cepat, lalu seluruh siswa wajib menyerahkan data mereka tanpa tahu risikonya","Pakai saja karena kelas lain sudah memakai aplikasi serupa, tanpa membahas data siapa yang terlibat atau risiko bila alatnya keliru atau berhenti bekerja"],answer:0,explain:"Adopsi AI yang memengaruhi banyak orang sebaiknya lewat pembahasan terbuka tentang manfaat, data, risiko, & pengaman.",hint:"Siapa yang terdampak, & apa rencana bila alatnya tidak bisa diandalkan suatu hari?"},
{n:91,type:"tf",micro:"AI tidak menggantikan hubungan & penilaian manusia",q:"Benar atau Salah: Untuk hal yang inti pada hubungan manusia & penilaian nilai (menghibur teman yang sedih, memutuskan hukuman yang adil, memilih arah hidup), AI sudah bisa menggantikan peran manusia sepenuhnya.",answer:false,explain:"AI bisa memberi informasi atau draf & membantu di pinggirannya, tapi empati sejati, tanggung jawab moral, & keputusan hidup tetap wilayah manusia.",hint:"Bisakah AI benar-benar menghibur temanmu, atau hanya menyarankan kata-kata?"},
{n:92,type:"mcq",micro:"Peran kita dalam membentuk AI",q:"Sebagai pengguna, cara kita ikut membentuk AI yang lebih baik:",options:["Menerima hasil AI tanpa bertanya, melapor, atau memeriksa, supaya tidak mengganggu perusahaan pembuatnya, dan mengabaikan pengaturan privasi atau layanan lain yang lebih baik","Melaporkan hasil yang keliru/bias, memakai pengaturan privasi, mendukung transparansi, memilih layanan yang lebih bertanggung jawab, & tidak menyebarkan misinformasi","Pengguna biasa tidak punya peran, karena semuanya ditentukan perusahaan dan suara pengguna tak mengubah apa-apa, jadi melapor, memilih layanan, atau mendukung transparansi hanya membuang waktu"],answer:1,explain:"Umpan balik & pilihan kolektif pengguna adalah tekanan nyata terhadap bagaimana sistem dirancang & dioperasikan.",hint:"Apa yang bisa jutaan pengguna yang melek AI lakukan bersama?"},
{n:93,type:"mcq",micro:"Ringkasan: AI dalam kehidupan sehari-hari",q:"Rangkuman paling tepat:",options:["AI adalah robot berbentuk manusia yang jarang kita temui, jadi kita tak perlu memikirkan data atau kebiasaan pakai; cukup percaya hasilnya, tanpa mencocokkan alat dengan tugas, memverifikasi hal penting, atau menuntut akuntabilitas","AI bersifat objektif dan keliru jarang terjadi, jadi hasilnya boleh dipercaya tanpa memeriksa, tanpa melindungi data, tanpa mengelola perhatian, dan tanpa menuntut transparansi atau akuntabilitas pembuatnya","AI di banyak layanan sehari-hari adalah program berbasis pola dari data; berguna tapi bisa keliru; memakainya bijak berarti mencocokkan alat dengan tugas, memverifikasi hal penting, menjaga data & perhatian, serta menuntut akuntabilitas"],answer:2,explain:"Inti: AI adalah alat berbasis pola yang meresap dalam hidup, dengan manfaat & risiko yang menuntut pemakaian sadar & warga yang melek.",hint:"Gabungkan: di mana-mana + berbasis pola + berguna tapi keliru + memengaruhi kita + pakai dengan sadar + tuntut akuntabilitas."},
{n:94,type:"open",micro:"Kapstone: peta AI dalam hidupku + rencana",q:"Buat 'peta AI dalam hidupku': (1) daftar minimal 6 titik nyata kamu berinteraksi dengan AI beserta tugas kecerdasannya, (2) untuk masing-masing, data apa yang kamu berikan (sadar/tidak sadar), (3) pilih 2 yang paling berpengaruh pada hidupmu & jelaskan pengaruh positif & negatifnya, (4) buat rencana 5 aturan pemakaian AI yang lebih sadar (verifikasi, data, waktu/perhatian, keragaman informasi, menjaga keterampilan), (5) satu hal yang akan kamu ajarkan ke anggota keluarga tentang AI di aplikasi mereka.",explain:"Kapstone menyatukan seluruh pemahaman: mengenali AI di kehidupan nyata, menyadari aliran data, menimbang pengaruh, membuat aturan pemakaian sadar, & menyebarkan literasi.",hint:"Bagian tersulit sering (2) — banyak data kita berikan tanpa sadar hanya dengan membuka aplikasi.",sample:"Jawaban lengkap mengisi kelima bagian. Contoh ringkas: (1) papan ketik prediktif (memprediksi kata) — data: semua yang kuketik; peta (memprediksi rute/waktu) — data: lokasi & pergerakanku; galeri (mengenali wajah/objek) — data: semua fotoku; umpan video (rekomendasi) — data: riwayat & durasi tonton; email spam (klasifikasi) — data: isi & pengirim email; toko daring (rekomendasi) — data: pencarian & pembelian. (2) Sebagian besar data diberikan 'tidak sadar' hanya dengan memakai aplikasi. (3) Umpan video: + menemukan konten belajar bermanfaat; − menyita waktu & menyempitkan minat. Peta: + hemat waktu & aman; − ketergantungan pada satu aplikasi & berbagi lokasi terus-menerus. (4) Aturan: verifikasi fakta dari AI dengan 1 sumber lain; jangan unggah dokumen sensitif ke layanan tak jelas; batas 20 menit/hari untuk aplikasi rekomendasi + notifikasi non-penting mati; seminggu sekali cari topik/sumber di luar rekomendasi; coba soal sendiri dulu sebelum tanya AI. (5) Mengajari nenek bahwa iklan yang 'mengikuti'-nya setelah mencari sesuatu itu normal & bukan tanda ponselnya diretas, serta cara mengenali pesan penipuan yang mendesak."},
{n:95,type:"mcq",micro:"Menilai sebuah 'kisah sukses AI'",q:"Berita: 'AI mendeteksi penyakit lebih cepat dari dokter di sebuah studi.' Pertanyaan yang bijak:",options:["Studi seperti apa (jumlah pasien, keragaman)? Bagaimana kinerjanya di rumah sakit nyata yang berbeda? Apa jenis kesalahannya? Apakah menggantikan atau membantu dokter?","Tidak perlu bertanya, karena AI lebih baik daripada dokter dalam segala hal, jadi hasil studi itu berlaku di mana saja, untuk setiap pasien, dan di setiap rumah sakit","Berarti dokter tidak dibutuhkan lagi, sehingga rumah sakit sebaiknya segera mengganti dokternya dengan sistem AI itu tanpa menguji jenis kesalahannya atau kinerjanya di tempat lain"],answer:0,explain:"Klaim keberhasilan AI perlu dinilai dari kualitas bukti, keterwakilan, mode kegagalan, & bagaimana ia sebenarnya dipakai (bantuan vs pengganti).",hint:"Apakah 'lebih baik dalam satu studi' sama dengan 'lebih baik di semua rumah sakit nyata'?"},
{n:96,type:"mcq",micro:"Kebiasaan digital sehat",q:"Kebiasaan yang paling melindungi dari sisi buruk AI sehari-hari:",options:["Menghindari semua teknologi digital sepenuhnya selama hidup, sebab hanya dengan begitu kita benar-benar aman dari sisi buruk AI","Jeda sebelum berbagi/percaya, memeriksa sumber, mengelola waktu & notifikasi, meninjau pengaturan privasi berkala, & menjaga keragaman sumber informasi","Mempercayai umpan dan rekomendasi sepenuhnya tanpa jeda, tanpa memeriksa sumber, dan tanpa mengatur notifikasi maupun pengaturan privasi"],answer:1,explain:"Beberapa kebiasaan sederhana & konsisten sangat mengurangi risiko misinformasi, kecanduan perhatian, & kehilangan privasi.",hint:"Apa kebiasaan kecil yang, diulang tiap hari, membuat pemakaian jauh lebih aman?"},
{n:97,type:"tf",micro:"AI di sekitar kita akan terus berkembang",q:"Benar atau Salah: AI akan makin banyak dipakai dalam layanan sehari-hari, jadi keterampilan mengenali, menilai, & memakainya dengan bijak akan makin bernilai seiring waktu.",answer:true,explain:"Semakin AI meresap, semakin penting setiap orang bisa membedakan pemakaian yang membantu dari yang menyesatkan atau merugikan.",hint:"Apakah peran AI dalam hidup sehari-hari cenderung bertambah atau berkurang?"},
{n:98,type:"mcq",micro:"Menutup: sikap yang tepat",q:"Sikap paling berguna terhadap AI dalam kehidupan sehari-hari:",options:["Takut dan menghindar total dari semua hal yang berkaitan dengan AI, tanpa mau mempelajari manfaat maupun cara memakainya dengan aman, dan tidak ikut menuntut sistem yang transparan atau adil","Kagum dan percaya buta pada semua hasil AI, tanpa pernah bertanya, memeriksa hal penting, mengelola data dan perhatian, atau menuntut sistem yang transparan dan adil dari pembuatnya","Ingin tahu & kritis: manfaatkan yang membantu, waspadai yang merugikan, verifikasi yang penting, kelola data & perhatian, & tuntut sistem yang transparan & adil"],answer:2,explain:"Bukan tekno-optimisme buta atau penolakan total, melainkan keingintahuan yang disertai kehati-hatian & tuntutan akan tanggung jawab.",hint:"Antara 'takut' & 'percaya buta', apa jalan tengahnya?"},
{n:99,type:"mcq",micro:"Menjelaskan AI ke orang lain",q:"Cara terbaik menjelaskan 'apa itu AI di aplikasi ini' ke teman yang bingung:",options:["Sebut tugas konkretnya ('ia menebak video yang kamu suka dari yang kamu tonton'), akui ia bisa salah, & tunjukkan pengaturan yang bisa mereka ubah","Bilang saja 'itu terlalu rumit untuk dijelaskan' dan sarankan temanmu untuk tidak usah mencari tahu tentang aplikasi itu, sebab hanya ahli yang paham","Bilang 'AI tahu segalanya' dan jarang keliru, jadi temanmu tidak perlu memeriksa atau mengubah pengaturan di aplikasi itu supaya hidupnya lebih mudah"],answer:0,explain:"Penjelasan yang baik: tugas konkret + pengakuan keterbatasan + langkah praktis yang memberdayakan.",hint:"Apa 3 hal yang membuat penjelasan berguna & tidak menakutkan?"},
{n:100,type:"open",micro:"Kapstone: panduan singkat 'AI di sekitar kita' untuk adik kelas",q:"Tulis panduan singkat (7–10 poin) berjudul 'Mengenali & Memakai AI di Aplikasi Sehari-hari' untuk siswa yang lebih muda. Cakup: apa itu AI secara sederhana, 3–4 contoh nyata + tugasnya, bahwa AI bisa salah, bahwa data kita dipakai, bahwa umpan/iklan dipilih algoritma (bukan semua yang ada), cara memeriksa informasi mencurigakan, cara mengatur waktu & privasi, & bahwa keputusan penting tetap milik manusia. Bahasa harus mudah dipahami anak.",explain:"Panduan baik menyederhanakan semua konsep inti tanpa menghilangkan yang penting: definisi, contoh, keterbatasan, data, kurasi umpan, verifikasi, pengelolaan waktu/privasi, & batas untuk keputusan berdampak — dalam bahasa yang ramah anak.",hint:"Bayangkan menjelaskan ke adik kelas 3: pakai contoh konkret & kalimat pendek, tapi jangan lewatkan 'AI bisa salah' & 'datamu dipakai'.",sample:"Contoh panduan: 1) AI adalah program yang belajar dari BANYAK contoh, lalu menebak — misalnya menebak foto mana yang ada kucingnya. 2) Contoh di aplikasimu: papan ketik menebak kata berikutnya; peta menebak jalan tercepat; galeri mengenali wajah; aplikasi video menebak video yang kamu suka. 3) AI sering benar, tapi kadang SALAH — jangan langsung percaya, apalagi soal angka atau berita. 4) Saat kamu memakai aplikasi, kamu memberi 'jejak' (apa yang kamu klik, tonton, cari). Aplikasi memakai jejak itu. 5) Yang kamu lihat di umpan bukan SEMUA hal — AI memilih & mengurutkan supaya kamu betah. Iklan juga dipilih dari aktivitasmu. 6) Kalau ada berita/video mengejutkan: berhenti, cek siapa yang mengunggah, cari di 2 sumber tepercaya, baru percaya/bagikan. 7) Atur waktu: pakai pengatur waktu, matikan notifikasi yang tidak penting. 8) Jangan bagikan data pribadi (alamat, foto, KTP keluarga) ke aplikasi/AI yang tidak jelas. 9) Untuk keputusan penting (menilai orang, memilih hukuman, memilih cita-cita), manusia yang memutuskan — AI cuma alat bantu. 10) Kalau bingung, tanya orang dewasa yang kamu percaya."},
];
